<script setup>
import {ref} from 'vue';import {useRouter,RouterLink} from 'vue-router';import {supabase} from '../services/supabase';const password=ref(''),confirm=ref(''),error=ref(''),message=ref(''),busy=ref(false),router=useRouter();async function update(){error.value='';if(password.value.length<8||password.value!==confirm.value){error.value='Use at least 8 characters and make sure both passwords match.';return}busy.value=true;const {error:e}=await supabase.auth.updateUser({password:password.value});if(e)error.value=e.message;else{message.value='Password updated. You can now sign in.';setTimeout(()=>router.push('/login?reset=1'),1200)}busy.value=false}
</script>
<template><div class="auth-wrap"><section class="auth-brand"><span class="brand-mark">C</span><h1>A fresh start.</h1><p>Choose a strong password to secure your Campus Gig account.</p></section><section class="auth-panel"><form class="auth-form" @submit.prevent="update"><RouterLink to="/login">← Back to sign in</RouterLink><h2 style="margin-top:25px">Set a new password</h2><div v-if="error" class="alert error">{{error}}</div><div v-if="message" class="alert success">{{message}}</div><div class="field"><label>New password</label><input v-model="password" class="input" type="password" required></div><div class="field"><label>Confirm new password</label><input v-model="confirm" class="input" type="password" required></div><button class="btn btn-primary" style="width:100%" :disabled="busy">{{busy?'Updating…':'Update password'}}</button></form></section></div></template>
